package art.gemosdodo.still;

import static org.junit.Assert.*;
import java.io.*;
import java.nio.*;
import org.junit.Test;

/** Numerical fixtures are generated by the actual existing Web Python pipeline,
 * using Apple's official unprojection and metric PLY, not mirrored Java math.
 */
public final class GaussianDisplayPreparerTest {
 private static int integer(DataInputStream in)throws IOException{return Integer.reverseBytes(in.readInt());}
 private static float floating(DataInputStream in)throws IOException{return Float.intBitsToFloat(integer(in));}
 private static double number(DataInputStream in)throws IOException{return Double.longBitsToDouble(Long.reverseBytes(in.readLong()));}
 private static final class Fixture implements Closeable {
  final DataInputStream in;final int kind,width,height,count,limit,expected;final double focal;final boolean adaptive;
  Fixture(String name)throws IOException{
   InputStream resource=getClass().getResourceAsStream("/"+name);if(resource==null)throw new IOException("Missing Python oracle fixture: "+name);
   in=new DataInputStream(new BufferedInputStream(resource));assertEquals(0x47534432,integer(in));kind=integer(in);width=integer(in);height=integer(in);count=integer(in);limit=integer(in);expected=integer(in);adaptive=integer(in)!=0;focal=number(in);
  }
  GaussianDisplayPreparer.Input input()throws IOException{
   float[] mean=new float[count*3],scale=new float[count*3],quat=new float[count*4],color=new float[count*3],alpha=new float[count];
   for(int i=0;i<count;i++){
    for(int c=0;c<3;c++)mean[i*3+c]=floating(in);for(int c=0;c<3;c++)scale[i*3+c]=floating(in);
    for(int c=0;c<4;c++)quat[i*4+c]=floating(in);for(int c=0;c<3;c++)color[i*3+c]=floating(in);alpha[i]=floating(in);
   }
   return new GaussianDisplayPreparer.Input(FloatBuffer.wrap(mean),FloatBuffer.wrap(scale),FloatBuffer.wrap(quat),FloatBuffer.wrap(color),FloatBuffer.wrap(alpha),width,height,focal);
  }
  public void close()throws IOException{in.close();}
 }
 private static void compare(float[] actual,float[] expected,String label){
  for(int c=0;c<16;c++){
   assertTrue(label+" finite field "+c,Float.isFinite(actual[c]));
   double tolerance=c>=4&&c<=9?1e-7+Math.abs(expected[c])*4e-4:c==10?0:5e-5;
   assertEquals(label+" field "+c,expected[c],actual[c],tolerance);
  }
 }
 @Test public void wholePipelineMatchesActualPythonPrepare()throws Exception{
  try(Fixture f=new Fixture("gaussian-display-synthetic-v2.bin")){
   assertEquals(0,f.kind);GaussianDisplayPreparer.Input input=f.input();GaussianDisplayPreparer.Analysis analysis=GaussianDisplayPreparer.analyze(input);
   assertEquals(f.adaptive,analysis.adaptive);ByteArrayOutputStream output=new ByteArrayOutputStream();int count=GaussianDisplayPreparer.write(input,analysis,f.limit,output);assertEquals(f.expected,count);
   FloatBuffer got=ByteBuffer.wrap(output.toByteArray()).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();
   for(int i=0;i<count;i++){float[] actual=new float[16],expected=new float[16];got.get(actual);for(int c=0;c<16;c++)expected[c]=floating(f.in);compare(actual,expected,"synthetic record "+i);}
   assertEquals(-1,f.in.read());
  }
 }
 @Test public void fullSceneSamplesMatchPythonJacobianAndFocus()throws Exception{
  try(Fixture f=new Fixture("gaussian-display-full-scene-100-v2.bin")){
   assertEquals(1,f.kind);double reference=number(f.in),boost=number(f.in);double[] low=new double[3],high=new double[3],focusLow=new double[3],focusHigh=new double[3];
   for(int c=0;c<3;c++)low[c]=number(f.in);for(int c=0;c<3;c++)high[c]=number(f.in);for(int c=0;c<3;c++)focusLow[c]=number(f.in);for(int c=0;c<3;c++)focusHigh[c]=number(f.in);float threshold=(float)number(f.in);
   GaussianDisplayPreparer.Input input=f.input();float[] weights=new float[f.count],x=new float[f.count],y=new float[f.count],z=new float[f.count];int[] sources=new int[f.count];
   for(int i=0;i<f.count;i++)weights[i]=floating(f.in);
   for(int i=0;i<f.count;i++){
    sources[i]=i;float depth=input.mean.get(i*3+2),warped=GaussianDisplayPreparer.warpedDepth(depth,(float)reference),factor=warped/depth;
    x[i]=input.mean.get(i*3)*input.sx*factor;y[i]=input.mean.get(i*3+1)*input.sy*factor;z[i]=warped;
   }
   GaussianDisplayPreparer.Analysis analysis=new GaussianDisplayPreparer.Analysis(sources,sources,x,y,z,weights,true,(float)reference,low,high,focusLow,focusHigh,threshold);
   for(int i=0;i<f.count;i++){
    float[] expected=new float[16],actual=new float[16];for(int c=0;c<16;c++)expected[c]=floating(f.in);
    GaussianDisplayPreparer.record(input,analysis,i,boost,actual);compare(actual,expected,"full synthetic scene sample "+i);
   }
   assertEquals(-1,f.in.read());
  }
 }
 @Test public void boundsAnalyzeAllPointsInsteadOfFirstSixtyThousand()throws Exception{
  int n=120001;float[] mean=new float[n*3],scale=new float[n*3],quat=new float[n*4],color=new float[n*3],alpha=new float[n];
  for(int i=0;i<n;i++){
   mean[i*3]=i<60000?0:100;mean[i*3+1]=(i%101)/100f;mean[i*3+2]=4;
   scale[i*3]=scale[i*3+1]=scale[i*3+2]=.01f;quat[i*4]=1;alpha[i]=.8f;color[i*3]=color[i*3+1]=color[i*3+2]=.4f;
  }
  GaussianDisplayPreparer.Input input=new GaussianDisplayPreparer.Input(FloatBuffer.wrap(mean),FloatBuffer.wrap(scale),FloatBuffer.wrap(quat),FloatBuffer.wrap(color),FloatBuffer.wrap(alpha),100,100,50);
  GaussianDisplayPreparer.Analysis analysis=GaussianDisplayPreparer.analyze(input);assertEquals(n,analysis.sources.length);assertFalse(analysis.adaptive);assertEquals(100,analysis.high[0],1e-6);
  ByteArrayOutputStream output=new ByteArrayOutputStream();assertEquals(250,GaussianDisplayPreparer.write(input,analysis,250,output));
  FloatBuffer got=ByteBuffer.wrap(output.toByteArray()).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();assertEquals(-.925,got.get(0),1e-6);assertEquals(.925,got.get((250-1)*16),1e-6);
 }
 @Test public void quantilesInterpolateAndWeightedValuesKeepStableOrder(){
  assertEquals(7.5,GaussianDisplayPreparer.quantile(new float[]{0,10},.75),1e-9);
  assertEquals(1,GaussianDisplayPreparer.weightedQuantile(new float[]{0,1,2},new float[]{1,2,1},.5),1e-7);
 }
 @Test public void analysisCancellationIsCheckedWithin4096Points()throws Exception{
  int n=6000;float[] mean=new float[n*3],scale=new float[n*3],q=new float[n*4],color=new float[n*3],alpha=new float[n];
  for(int i=0;i<n;i++){mean[i*3+2]=1;scale[i*3]=scale[i*3+1]=scale[i*3+2]=.01f;q[i*4]=1;alpha[i]=.8f;}
  GaussianDisplayPreparer.Input input=new GaussianDisplayPreparer.Input(FloatBuffer.wrap(mean),FloatBuffer.wrap(scale),FloatBuffer.wrap(q),FloatBuffer.wrap(color),FloatBuffer.wrap(alpha),100,100,100);
  final int[] checks={0};
  try{GaussianDisplayPreparer.analyze(input,()->++checks[0]>=3);fail("Expected cancellation during the first validity pass");}catch(InterruptedIOException expected){assertEquals(3,checks[0]);}
 }
 @Test public void cancelledWriteDoesNotProducePartialRecords()throws Exception{
  try(Fixture f=new Fixture("gaussian-display-synthetic-v2.bin")){
   GaussianDisplayPreparer.Input input=f.input();GaussianDisplayPreparer.Analysis analysis=GaussianDisplayPreparer.analyze(input);ByteArrayOutputStream output=new ByteArrayOutputStream();
   try{GaussianDisplayPreparer.write(input,analysis,257,output,()->true);fail("Expected write cancellation");}catch(InterruptedIOException expected){assertEquals(0,output.size());}
  }
 }

}
